def find_robot_arm(N, points):
    def can_reach(dx, dy, d):
        # Check if dx and dy can be reached using d with moves L, R, D, U
        if abs(dx) > sum(d) or abs(dy) > sum(d):
            return False
        dp = [[False] * (abs(dx) + 1) for _ in range(abs(dy) + 1)]
        dp[0][0] = True

        for di in d:
            ndp = [row[:] for row in dp]
            for x in range(len(dp)):
                for y in range(len(dp[0])):
                    if dp[x][y]:
                        if x + di <= len(dp) - 1:
                            ndp[x + di][y] = True
                        if y + di <= len(dp[0]) - 1:
                            ndp[x][y + di] = True
                        if x >= di:
                            ndp[x - di][y] = True
                        if y >= di:
                            ndp[x][y - di] = True
            dp = ndp

        return dp[abs(dx)][abs(dy)]

    def backtrack(dx, dy, d, path):
        if len(path) == len(d):
            if dx == 0 and dy == 0:
                return True
            return False

        for move in ['L', 'R', 'D', 'U']:
            if move == 'L':
                if backtrack(dx + d[len(path)], dy, d, path + move):
                    return True
            elif move == 'R':
                if backtrack(dx - d[len(path)], dy, d, path + move):
                    return True
            elif move == 'D':
                if backtrack(dx, dy + d[len(path)], d, path + move):
                    return True
            elif move == 'U':
                if backtrack(dx, dy - d[len(path)], d, path + move):
                    return True

        return False

    for m in range(1, 41):
        for d in itertools.combinations_with_replacement(range(1, 10**13 + 1), m):
            if all(can_reach(points[i+1][0] - points[i][0], points[i+1][1] - points[i][1], d) for i in range(N-1)):
                paths = []
                for i in range(N):
                    path = ''
                    dx, dy = points[i+1][0] - points[i][0], points[i+1][1] - points[i][1]
                    if backtrack(dx, dy, d, path):
                        paths.append(path)
                    else:
                        break
                else:
                    return f"{m}\n{' '.join(map(str, d))}\n\n".join(paths)

    return "-1"

