def can_reach_target(X, Y, d):
    # Try to reach (X, Y) starting from (0, 0)
    queue = [(0, 0)]
    visited = set()
    while queue:
        x, y = queue.pop(0)
        if (x, y) == (X, Y):
            return True
        if (x, y) in visited:
            continue
        visited.add((x, y))
        for dx, dy in [(-d, 0), (d, 0), (0, -d), (0, d)]:
            nx, ny = x + dx, y + dy
            queue.append((nx, ny))
    return False

