def can_form_valid_sequence(N, AB):
    # Initialize variables
    occupied_floors = set()
    valid = True

    for i in range(N):
        A, B = AB[i]

        # Skip if either A or B is -1
        if A == -1 or B == -1:
            continue

        # Check if the sequence is valid
        if A >= B:
            valid = False
            break

        # Check if the floors are already occupied by someone else
        for floor in range(A + 1, B):
            if floor in occupied_floors:
                valid = False
                break

        # Mark the floors as occupied
        for floor in range(A + 1, B):
            occupied_floors.add(floor)

    # Print the result
    if valid:
        print("Yes")
    else:
        print("No")

