def is_valid_sequence(N, A, B):
    # Calculate initial C values for known positions
    known_C = {}
    for i in range(N):
        if A[i] != -1 and B[i] != -1:
            C = B[i] - A[i] - 1
            if C in known_C:
                known_C[C].append(i)
            else:
                known_C[C] = [i]

    # Check if there are multiple C values
    if len(known_C) > 1:
        return False

    # Fill in unknown values
    used_floors = set()
    for i in range(N):
        if A[i] == -1:
            for j in range(1, 2 * N + 1):
                if j not in used_floors:
                    A[i] = j
                    used_floors.add(j)
                    break

        if B[i] == -1:
            for j in range(A[i] + 2, 2 * N + 1):
                if j not in used_floors:
                    B[i] = j
                    used_floors.add(j)
                    break

    # Verify the final sequence
    current_floor = 1
    visited = set()
    for i in range(N):
        if current_floor == A[i]:
            current_floor = B[i]
            visited.add((current_floor, A[i]))
        elif current_floor == B[i]:
            continue
        else:
            return False

    if current_floor != 2 * N or len(visited) != N:
        return False

    return True

