def is_valid_sequence(N, A, B):
    # Create a list to keep track of used floors
    used_floors = [False] * (2 * N + 1)

    for i in range(N):
        ai, bi = A[i], B[i]

        if ai == -1:
            # Find a valid ai
            for a in range(1, 2 * N):
                if not used_floors[a]:
                    used_floors[a] = True
                    ai = a
                    break
            else:
                return "No"

        if bi == -1:
            # Find a valid bi
            for b in range(ai + 2, 2 * N + 1):
                if not used_floors[b]:
                    used_floors[b] = True
                    bi = b
                    break
            else:
                return "No"

        # Check the condition C_i
        ci = bi - ai - 1
        if ci != B[i] - A[i] - 1:
            return "No"

        # Mark the floors used by this person
        for j in range(ai, bi):
            if used_floors[j]:
                return "No"
            used_floors[j] = True

    return "Yes"

