    # Dictionary to store the segments
    segments = {}

    for i in range(N):
        if A[i] != -1 and B[i] != -1:
            if (A[i], B[i]) in segments:
                return False
            segments[(A[i], B[i])] = True

    # Try to fill in the gaps
    for i in range(N):
        if A[i] == -1:
            for start in range(1, 2*N + 1):
                if (start, B[i]) not in segments:
                    A[i] = start
                    break
            else:
                return False

        if B[i] == -1:
            for end in range(1, 2*N + 1):
                if (A[i], end) not in segments:
                    B[i] = end
                    break
            else:
                return False

    # Check the conditions
    for i in range(N):
        for j in range(i+1, N):
            if A[i] == -1 or A[j] == -1 or B[i] == -1 or B[j] == -1:
                continue

            if B[i] - A[i] - 1 != B[j] - A[j] - 1:
                return False

    return True

