    elevator_state = {}

    # Function to check if a given assignment is valid
    def is_valid_assignment(A, B):
        # Create a copy of the elevator state
        current_state = elevator_state.copy()

        # Process each person
        for ai, bi in zip(A, B):
            if ai == -1:
                ai = min(current_state.keys()) + 1

            if bi == -1:
                bi = max(current_state.keys()) + 2

            # Update the elevator state
            if ai not in current_state:
                current_state[ai] = 0
            if bi not in current_state:
                current_state[bi] = 0

            # Check the counts of stops
            for key in current_state:
                if key != ai and key != bi:
                    if current_state[key] != len(current_state) - 1:
                        return False

            # Add the new person to the elevator state
            current_state[ai] += 1
            current_state[bi] -= 1

        return True

    # Try to find a valid assignment
