def can_form_valid_sequence(N, pairs):
    # Initialize variables
    used_floors = set()

    # Try to deduce missing values
    for i in range(N):
        A, B = pairs[i]
        if A == -1:
            for a in range(1, 2*N+1):
                if a not in used_floors and a < B:
                    pairs[i] = (a, B)
                    break
        if B == -1:
            for b in range(B+1, 2*N+1):
                if b not in used_floors and b > A:
                    pairs[i] = (A, b)
                    break

    # Check if all floors are used within the valid range
    for A, B in pairs:
        if A != -1:
            used_floors.add(A)
        if B != -1:
            used_floors.add(B)

    if len(used_floors) != 2*N:
        return "No"

    # Calculate C_i and check consistency
    C = [0] * N
    for i in range(N):
        A, B = pairs[i]
        if A == -1 or B == -1:
            continue
        C[i] = B - A - 1

    for i in range(1, N):
        if C[i] != C[0]:
            return "No"

    return "Yes"

