def check_elevator_records(N, records):
    # Initialize sets to store possible values for each floor
    floors = [[] for _ in range(2 * N + 1)]

    # Process each record
    for A, B in records:
        if A != -1 and B != -1:
            C = B - A - 1
            floors[A].append(C)
            floors[B].append(-1)  # Mark B as not needed anymore

    # Check if there are enough constraints
    if len([x for x in floors if x]) < 2 * N:
        return "No"

    # Deduce the values for each floor
    for i in range(1, 2 * N + 1):
        if not floors[i]:
            continue

        # Find the most common C value for the current floor
        from collections import Counter
        counts = Counter(floors[i])
        most_common_C = counts.most_common(1)[0][0]

        # Update the sets for the current floor and its neighbors
        for j in range(max(1, i - most_common_C), min(2 * N + 1, i + most_common_C + 1)):
            if j != i:
                floors[j].append(most_common_C)

    # Verify the solution
    for i in range(1, 2 * N + 1):
        if not floors[i]:
            return "No"

    return "Yes"

