def can_determine_elevator_stops(N, A, B):
    # Calculate known C_i values
    known_C = []
    for a, b in zip(A, B):
        if a != -1 and b != -1:
            known_C.append(b - a - 1)

    # Count the number of known C_i values
    num_known_C = len(known_C)

    # If we don't have enough known C_i values to determine all, return "No"
    if num_known_C < N:
        return "No"

    # Sum of known C_i values
    sum_known_C = sum(known_C)

    # If the sum of known C_i values is not N-1, return "No"
    if sum_known_C != N - 1:
        return "No"

    # Assign values to unknown records
    unknown_indices = [i for i in range(N) if A[i] == -1 or B[i] == -1]
    for i in unknown_indices:
        if A[i] == -1:
            A[i] = 1
        if B[i] == -1:
            B[i] = A[i] + known_C[unknown_indices.index(i)] + 2

    # Verify the solution
    for i in range(N):
        a, b = A[i], B[i]
        if a == -1 or b == -1:
            continue
        c = b - a - 1
        for j in range(N):
            if i != j:
                if A[j] <= a < b <= B[j]:
                    if b - A[j] - 1 != c:
                        return "No"

    return "Yes"

