    for i in range(n):
        for j in range(i + 1, n):
            if A[i] != -1 and B[i] != -1 and A[j] != -1 and B[j] != -1:
                if max(A[i], A[j]) <= min(B[i], B[j]):
                    C_i = B[i] - A[i] - 1
                    C_j = B[j] - A[j] - 1
                    if C_i != C_j:
                        return False
    return True

def backtrack(N, A, B, index):
    if index == N:
        return is_valid(A, B)

    for a in range(1, 2 * N + 1):
        for b in range(a + 1, 2 * N + 1):
            A[index] = a
            B[index] = b
            if backtrack(N, A, B, index + 1):
                return True
            A[index] = -1
            B[index] = -1

    return False

