def find_sequence(M, K):
    if M == 0:
        if K == 0:
            return [0, 0]
        else:
            return []

    n = 2 ** M

    # Generate pairs of numbers from 0 to n-1
    pairs = [(i, i) for i in range(n)]

    # Try to construct the sequence
    def backtrack(seq, used):
        if len(seq) == 2 * n:
            if verify_sequence(seq, K):
                return seq
            return None

        for i in range(n):
            if i not in used:
                used.add(i)
                seq.append(i)
                result = backtrack(seq, used)
                if result:
                    return result
                seq.pop()
                used.remove(i)

        return None

    result = backtrack([], set())
    return result

def verify_sequence(seq, K):
    n = len(seq) // 2
    for i in range(n):
        start = i * 2
        end = start + 1
        current_xor = seq[start]
        while end < len(seq):
            current_xor ^= seq[end]
            if current_xor == K:
                end += 1
            else:
                break
        if end != start + 1:
            return False
    return True

