def find_sequence(M, K):
    n = 2 ** (M + 1)
    if K == 0:
        # Special case: If K is 0, we can simply repeat the same element twice
        return [0] * n

    # Generate pairs of numbers from [0, 2^M - 1]
    pairs = [(i, i) for i in range(2 ** M)]

    def dfs(index, current_xor, path):
        if index == len(pairs):
            if current_xor == K and len(path) == n:
                return path
            return None

        # Try adding both pairs
        result = []
        for i in range(index, len(pairs)):
            new_path = path + [pairs[i][0], pairs[i][1]]
            new_xor = current_xor ^ pairs[i][0] ^ pairs[i][1]
            result.append(dfs(i + 1, new_xor, new_path))

        return next(filter(None, result), None)

    sequence = dfs(0, 0, [])
    if sequence:
        return " ".join(map(str, sequence))
    else:
        return "-1"

