    dp[0][0] = 1

    for i in range(1, n + 1):
        char = s[i - 1]
        if char.isdigit():
            d = int(char)
            for j in range(13):
                dp[i][(j * 10 + d) % 13] += dp[i - 1][j]
                dp[i][(j * 10 + d) % 13] %= MOD
