def count_valid_numbers(s):
    n = len(s)

    # If the string contains no '?', check if it's already divisible by 13
    if s.count('?') == 0:
        return int(int(s) % 13 == 5)

    # Initialize dp array
    dp = [[0] * 10 for _ in range(n)]

    # Base case: one way to form a number ending with each digit using zero characters
    for j in range(10):
        dp[0][j] = 1

    # Fill dp table
    for i in range(1, n):
        if s[i].isdigit():
            d = int(s[i])
            for j in range(10):
                dp[i][j] = dp[i-1][(j * 10 + d) % 13]
        else:
            for j in range(10):
                dp[i][j] = sum(dp[i-1][k] for k in range(10)) % MOD

    # Sum up all valid numbers ending with a digit that gives a remainder of 5 when divided by 13
    result = sum(dp[n-1][j] for j in range(10) if (j * 13 + 5) % 13 == 0)

