def count_valid_k(N):
    # Set to store unique divisors
    divisors = set()

    # Find all divisors of N
    for i in range(2, int(N**0.5) + 1):
        if N % i == 0:
            divisors.add(i)
            divisors.add(N // i)

    # Add N itself if it's greater than 1
    if N > 1:
        divisors.add(N)

    # Remove 1 and N from the set since K cannot be 1 or N
    divisors.discard(1)
    divisors.discard(N)

    # Function to check if N can be reduced to 1 using K
    def can_reduce_to_one(K):
        current = N
        while current >= K:
            if current % K == 0:
                current //= K
            else:
                current -= K
            if current == 1:
                return True
        return False

    # Count valid K values
    valid_k_count = sum(can_reduce_to_one(k) for k in divisors)

    return valid_k_count

