def sum_of_gcds(N, K):
    if N == 1:
        return K % MOD
    if K == 1:
        return 1 % MOD

    total_sum = 0
    primes = []

    # Generate all primes up to K using Sieve of Eratosthenes
    sieve = [True] * (K + 1)
    for i in range(2, int(K**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, K + 1, i):
                sieve[j] = False
    primes = [i for i in range(2, K + 1) if sieve[i]]

    for p in primes:
        count = 0
        for k in range(1, K // p + 1):
            count += (K // (p * k)) ** N
            if k > 1:
                count -= (K // ((k * p) ** 2)) ** N

        total_sum = (total_sum + p * count) % MOD

    return total_sum

