    return fact

def inv_factorial(n, mod):
    inv_fact = [1] * (n + 1)
    inv_fact[n] = pow(factorial(n, mod), mod - 2, mod)
    for i in range(n - 1, 0, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % mod
    return inv_fact

def binomial_coefficient(n, k, mod):
