    for i in range(2, N + 1):
        temp = i
        for p in range(2, int(math.sqrt(temp)) + 1):
            while temp % p == 0:
                prime_factors[p] += 1
                temp //= p
        if temp > 1:
            prime_factors[temp] += 1

    # Check all combinations of exponents to see if they form 75 divisors
    def backtrack(index, current_product, path):
        if index == len(prime_factors):
            if current_product == 75:
                nonlocal count
                count += 1
            return

        p = list(prime_factors.keys())[index]
        for exp in range(prime_factors[p], -1, -1):
            new_product = current_product * (exp + 1)
            if new_product <= 75:
                path.append(exp)
                backtrack(index + 1, new_product, path)
                path.pop()

    count = 0
    backtrack(0, 1, [])

    return count

