    return ((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2) ** 0.5

def make_circle(points: List[Tuple[int, int]]) -> Tuple[float, float, float]:
    if not points:
        return (0, 0, 0)
    if len(points) == 1:
        return (points[0][0], points[0][1], 0)

    def helper(points: List[Tuple[int, int]], boundary_points: List[Tuple[int, int]]) -> Tuple[float, float, float]:
        if not points or len(boundary_points) == 3:
            cx, cy = 0, 0
            r = 0
            for bp in boundary_points:
                dx, dy = bp[0] - cx, bp[1] - cy
                r = max(r, dist(bp, (cx, cy)))
            return (cx, cy, r)

        p = points.pop()
        c, r = helper(points, boundary_points)
        if dist((c, r), p) <= r:
            points.append(p)
            return (c, r)

        boundary_points.append(p)
        c1, r1 = helper(points, boundary_points[:-1])
        boundary_points.pop()
        c2, r2 = helper(points, boundary_points[:-1])

        points.append(p)
        return min((c1, r1), (c2, r2))

    return helper(points[:], [])

