    n = len(points)
    if n <= 3:
        return points

    lower = []
    upper = []

    def turn(p, q, r):
        val = cross_product(q, r) - cross_product(r, p) - cross_product(p, q)
        if val == 0:
            return 0
        elif val > 0:
            return 1
        else:
            return -1

    points.sort()
    for point in points:
        while len(lower) >= 2 and turn(lower[-2], lower[-1], point) < 0:
            lower.pop()
        lower.append(point)

    for point in reversed(points):
        while len(upper) >= 2 and turn(upper[-2], upper[-1], point) < 0:
            upper.pop()
        upper.append(point)

    upper.pop()
    hull = lower + upper
    return hull

