import math
from typing import List, Tuple

# Function to calculate the cross product of vectors AB and AC
def cross_product(A: Tuple[int, int], B: Tuple[int, int], C: Tuple[int, int]) -> float:
    return (B[0] - A[0]) * (C[1] - A[1]) - (B[1] - A[1]) * (C[0] - A[0])

# Function to calculate the determinant of a 3x3 matrix formed by points A, B, C
def determinant(A: Tuple[int, int], B: Tuple[int, int], C: Tuple[int, int]) -> float:
    return (A[0] * (B[1] - C[1]) + B[0] * (C[1] - A[1]) + C[0] * (A[1] - B[1]))

# Function to calculate the circumcenter and radius of the circumcircle of triangle ABC
def circumcircle(A: Tuple[int, int], B: Tuple[int, int], C: Tuple[int, int]) -> Tuple[Tuple[float, float], float]:
    D = 2 * determinant(A, B, C)
    Ux = ((A[0]**2 + A[1]**2) * (B[1] - C[1]) +
          (B[0]**2 + B[1]**2) * (C[1] - A[1]) +
          (C[0]**2 + C[1]**2) * (A[1] - B[1])) / D
    Uy = ((A[0]**2 + A[1]**2) * (C[0] - B[0]) +
          (B[0]**2 + B[1]**2) * (A[0] - C[0]) +
          (C[0]**2 + C[1]**2) * (B[0] - A[0])) / D
    center = (Ux, Uy)
    radius = math.sqrt((A[0] - Ux)**2 + (A[1] - Uy)**2)
    return center, radius

# Andrew's Monotone Chain Algorithm to find the convex hull
def convex_hull(points: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    points.sort()
    lower = []
    for point in points:
        while len(lower) >= 2 and cross_product(lower[-2], lower[-1], point) < 0:
            lower.pop()
        lower.append(point)

    upper = []
    for point in reversed(points):
        while len(upper) >= 2 and cross_product(upper[-2], upper[-1], point) < 0:
            upper.pop()
        upper.append(point)

    # Remove the last point because it's repeated
    upper.pop()

    return lower + upper

# Main function to find the minimum enclosing circle
def min_enclosing_circle(points: List[Tuple[int, int]]) -> float:
    hull = convex_hull(points)
    n = len(hull)

    if n == 1:
        return 0.0

    if n == 2:
        return math.dist(hull[0], hull[1]) / 2.0

    def add_point(circle, point):
        xc, yc, r = circle
        dx, dy = point[0] - xc, point[1] - yc
        dist = dx * dx + dy * dy

        if dist <= r * r:
            return circle

        if dist == 0:
            return circle

        r = math.sqrt(dist)
        angle = math.atan2(dy, dx)

        def bisect(a, b):
            mid_angle = (a + b) / 2
            mid_xc = xc + r * math.cos(mid_angle)
            mid_yc = yc + r * math.sin(mid_angle)
            mid_circle = (mid_xc, mid_yc, r)
            if add_point(mid_circle, point) != mid_circle:
                return bisect(a, mid_angle)
            else:
                return bisect(mid_angle, b)

        new_angle = bisect(0, 2 * math.pi)
        new_xc = xc + r * math.cos(new_angle)
        new_yc = yc + r * math.sin(new_angle)
        new_radius = max(r, math.dist((new_xc, new_yc), point))
        return (new_xc, new_yc, new_radius)

    circle = (0, 0, 0)
    for point in hull:
        circle = add_point(circle, point)

    return circle[2]

