def can_partition(S):
    if len(S) == 0:
        return True
    if len(S) % 2 != 0:
        return False

    # Find the maximum element
    max_val = max(S)

    # Remove the maximum element
    S.remove(max_val)

    # Check if there is a corresponding pair
    if max_val - 1 not in S:
        return False
    else:
        S.remove(max_val - 1)

    # Recursively check the remaining elements
    return can_partition(S)

