def find_assignment(N, s):
    if N < 3:
        return -1

    # Initialize variables
    visited = [False] * N
    species = [''] * N

    def dfs(node, prev_species):
        if visited[node]:
            return True

        visited[node] = True
        species[node] = 'S' if prev_species == 'W' else 'W'

        if node == 0:
            if s[0] != (species[(node + 1) % N] == species[(node - 1 + N) % N]):
                return False
        elif node == N - 1:
            if s[N - 1] != (species[(node + 1) % N] == species[(node - 1 + N) % N]):
                return False
        else:
            if s[node] != (species[(node + 1) % N] == species[(node - 1 + N) % N]):
                return False

        if node > 0 and not dfs((node + 1) % N, species[node]):
            return False
        if node < N - 1 and not dfs((node - 1 + N) % N, species[node]):
            return False

        return True

    for i in range(N):
        if not visited[i]:
            if not dfs(i, 'S'):
                if not dfs(i, 'W'):
                    return -1

    return ''.join(species)

