def assign_species(N, s):
    # Try assuming the first animal is a sheep
    for i in range(2 * N):
        if i < N:
            current = 'S'
        else:
            current = 'W'

        # Check consistency
        consistent = True
        for j in range(N):
            left = (j - 1 + N) % N
            right = (j + 1) % N
            if (current == s[j] and current != s[left]) or (current != s[j] and current == s[left]):
                consistent = False
                break

        if consistent:
            result = [current]
            for k in range(1, N):
                if (result[-1] == s[k] and result[-1] != s[(k - 1 + N) % N]) or (result[-1] != s[k] and result[-1] == s[(k - 1 + N) % N]):
                    result.append('W' if result[-1] == 'S' else 'S')
                else:
                    result.append(result[-1])
            return ''.join(result)

    return "-1"

