def is_valid_assignment(N, s, assignment):
    for i in range(N):
        left = assignment[(i - 1) % N]
        right = assignment[i]
        expected = 'o' if left == right else 'x'
        if s[i] != expected:
            return False
    return True

def solve(N, s):
    # Try assigning the first animal as a sheep (S)
    assignment = ['S'] * N
    if is_valid_assignment(N, s, assignment):
        return ''.join(assignment)

    # Try assigning the first animal as a wolf (W)
    assignment[0] = 'W'
    if is_valid_assignment(N, s, assignment):
        return ''.join(assignment)

    return '-1'

