def solve_zoo(N, s):
    # Helper function to check if the assignment is valid
    def is_valid_assignment(assignment):
        for i in range(N):
            left = assignment[(i - 1) % N]
            right = assignment[(i + 1) % N]
            if s[i] == 'o':
                if (left != right):
                    return False
            else:
                if (left == right):
                    return False
        return True

    # Try assigning the first animal as a sheep
    assignment = ['S'] * N
    if is_valid_assignment(assignment):
        return ''.join(assignment)

    # If the first animal as a sheep doesn't work, try assigning it as a wolf
    assignment[0] = 'W'
    if is_valid_assignment(assignment):
        return ''.join(assignment)

    # If neither works, return -1
    return '-1'

