def sort_with_swaps(P):
    N = len(P)
    inversions = count_inversions(P)

    if inversions > N - 1:
        return -1

    operations = []
    for i in range(N - 1):
        for j in range(i + 1, N):
            if P[i] > P[j]:
                P[i], P[j] = P[j], P[i]
                operations.append(j)
                break

    return operations

