def sort_permutation(N, P):
    # Create a list of tuples (value, index)
    elements = [(P[i], i) for i in range(N)]

    # Sort the elements based on their value
    sorted_elements = sorted(elements)

    # Dictionary to store the target positions of each element
    target_positions = {value: idx for idx, (value, _) in enumerate(sorted_elements)}

    # List to store the operations
    operations = []

    # Perform the swaps
    visited = [False] * N

    for i in range(N):
        if visited[i]:
            continue

        cycle = []
        x = i

        while not visited[x]:
            visited[x] = True
            cycle.append(x)
            x = target_positions[P[x]]

        # If the cycle length is even, we can sort it with adjacent swaps
        if len(cycle) % 2 == 0:
            for j in range(len(cycle) // 2):
                for k in range(j, len(cycle) - j - 1):
                    operations.append(cycle[k])
        else:
            # If the cycle length is odd, it's impossible to sort
            return -1

    return operations

