def sort_permutation(N, P):
    # Create a list of tuples (value, original_index)
    indexed_P = [(P[i], i) for i in range(N)]

    # Sort the list based on the value
    sorted_P = sorted(indexed_P)

    # Dictionary to store the target index of each value
    target_indices = {value: idx for idx, (value, _) in enumerate(sorted_P)}

    # List to store the sequence of operations
    operations = []

    # Set to keep track of visited indices
    visited = set()

    for i in range(N):
        if i not in visited:
            cycle = []
            x = i

            while x not in visited:
                visited.add(x)
                cycle.append(x)
                x = target_indices[P[x]]

            # Reverse the cycle to make it increasing
            cycle.reverse()

            # Append operations for this cycle
            for j in range(1, len(cycle)):
                operations.append(cycle[j])

    # Check if the number of operations is N-1
    if len(operations) != N - 1:
        return -1

    return operations

