def min_swaps_to_sort(permutation):
    n = len(permutation)
    visited = [False] * n
    swaps = 0

    for i in range(n):
        if not visited[i]:
            cycle_size = 0
            x = i

            while not visited[x]:
                visited[x] = True
                x = permutation[x] - 1
                cycle_size += 1

            if cycle_size > 1:
                swaps += (cycle_size - 1)

    if swaps > n - 1:
        return -1

    # Generate the sequence of swaps
    result = []
    for i in range(n):
        if permutation[i] != i + 1:
            for j in range(i + 1, n):
                if permutation[j] == i + 1:
                    result.append(j + 1)
                    permutation[i], permutation[j] = permutation[j], permutation[i]
                    break

    return result

