    # Create a list to store the positions of each element
    pos = [0] * (N + 1)
    for i in range(N):
        pos[P[i]] = i

    # Initialize the number of swaps
    swaps = 0

    # Iterate over each element and move it to its correct position
    for i in range(1, N + 1):
        while pos[i] != i - 1:
            # Find the correct position of the current element
            correct_pos = pos[i]

            # Swap the current element with the next element
            P[correct_pos], P[correct_pos + 1] = P[correct_pos + 1], P[correct_pos]
            pos[P[correct_pos]], pos[P[correct_pos + 1]] = pos[P[correct_pos + 1]], pos[P[correct_pos]]

            # Update the number of swaps
            swaps += 1

            # Check if the current element is now in the correct position
            if pos[i] == i - 1:
                break

    # If the number of swaps exceeds N-1, it means sorting is not possible
    if swaps > N - 1:
        return -1

    # Print the number of swaps
    print(swaps)

    # Print the sequence of swaps
    for i in range(swaps):
        print(i + 1)

