def sort_permutation(N, P):
    # Create a mapping of each element to its index
    pos = {P[i]: i for i in range(N)}

    # Initialize a list to store the operations
    operations = []

    # Perform bubble sort-like swaps
    for i in range(N - 1):
        while pos[P[i]] > i:
            # Find the correct position of P[i]
            correct_pos = pos[P[i]]

            # Swap P[i] and P[correct_pos]
            P[i], P[correct_pos] = P[correct_pos], P[i]

            # Update positions in the dictionary
            pos[P[i]], pos[P[correct_pos]] = pos[P[correct_pos]], pos[P[i]]

            # Record the operation
            operations.append(correct_pos)

    # Check if the permutation is sorted
    if all(P[i] == i + 1 for i in range(N)):
        return operations
    else:
        return [-1]

