def sort_permutation(N, P):
    inversions = count_inversions(P)
    if inversions % 2 != 0:
        return "-1"

    operations = []
    sorted_indices = {val: idx for idx, val in enumerate(sorted(P))}

    for i in range(N):
        while P[i] != i + 1:
            target_idx = sorted_indices[i + 1]
            # Perform the required transpositions
            if i + 1 == target_idx + 1:
                operations.append(target_idx)
                P[i], P[target_idx] = P[target_idx], P[i]
            else:
                operations.append(target_idx)
                P[i], P[target_idx] = P[target_idx], P[i]
                operations.append(target_idx - 1)
                P[target_idx], P[target_idx - 1] = P[target_idx - 1], P[target_idx]

    return "\n".join(map(str, operations))

