def is_snuke_number(n, s_n):
    # Check if n is a Snuke number by comparing it with all larger numbers up to a certain limit
    # Here we use a heuristic to limit the range for practical purposes
    limit = 10**15
    for m in range(n + 1, min(limit, n * 10)):
        s_m = digit_sum(m)
        if n / s_n > m / s_m:
            return False
    return True

def k_smallest_snuke_numbers(K):
    heap = []
    heapq.heappush(heap, (digit_sum(1), 1))

    snuke_numbers = []
    while len(snuke_numbers) < K:
        _, n = heapq.heappop(heap)
        if is_snuke_number(n, digit_sum(n)):
            snuke_numbers.append(n)
        else:
            # Push next candidate numbers into the heap
            for multiplier in range(2, 10):
                next_n = n * multiplier
                heapq.heappush(heap, (digit_sum(next_n), next_n))

    return snuke_numbers

