def find_snuke_numbers(K):
    snuke_numbers = []
    heap = [(n, n) for n in range(1, 10)]
    heapq.heapify(heap)

    while len(snuke_numbers) < K:
        n, _ = heapq.heappop(heap)
        if is_snuke_number(n, snuke_numbers):
            snuke_numbers.append(n)
            for next_n in range(n + 1, n + 10):
                heapq.heappush(heap, (next_n, next_n))

    return snuke_numbers[:K]

