                    if grid[i][j] == 0:
                        grid[i][j] = color
                        if is_valid(grid, i, j, color):
                            placed = True
                            break
                if placed:
                    break
            if not placed:
                raise Exception("Failed to place color {} in a valid 4-connected component".format(color))
            count -= 1

    return grid

