def paint_grid(H, W, N, counts):
    grid = [[0] * W for _ in range(H)]

    # Directions for moving right and down
    directions = [(0, 1), (1, 0)]

    x, y = 0, 0
    direction_index = 0

    for i in range(N):
        count = counts[i]
        while count > 0:
            grid[x][y] = i + 1
            count -= 1

            # Move to the next position
            dx, dy = directions[direction_index]
            nx, ny = x + dx, y + dy

            # Check if the new position is within bounds
            if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == 0:
                x, y = nx, ny
            else:
                # Change direction
                direction_index = 1 - direction_index
                dx, dy = directions[direction_index]
                x, y = x + dx, y + dy

                # Adjust to stay within bounds
                if x < 0:
                    x = 0
                elif x >= H:
                    x = H - 1
                if y < 0:
                    y = 0
                elif y >= W:
                    y = W - 1

    return grid

