def generate_spiral(H, W):
    dx, dy = [0, 1, 0, -1], [1, 0, -1, 0]
    x, y, d = 0, 0, 0
    grid = [[0] * W for _ in range(H)]

    for i in range(1, H * W + 1):
        grid[x][y] = i
        nx, ny = x + dx[d], y + dy[d]
        if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == 0:
            x, y = nx, ny
        else:
            d = (d + 1) % 4
            x, y = x + dx[d], y + dy[d]

    return grid

