def paint_grid(H, W, N, counts):
    grid = [[0] * W for _ in range(H)]

    def place_block(color, x, y, dx, dy):
        nonlocal grid
        if x < 0 or x >= H or y < 0 or y >= W or grid[x][y] != 0:
            return False
        grid[x][y] = color
        counts[color] -= 1
        if counts[color] == 0:
            return True
        if place_block(color, x + dx, y + dy, dx, dy):
            return True
        return False

    for color in range(1, N + 1):
        for i in range(H):
            for j in range(W):
                if grid[i][j] == 0:
                    if place_block(color, i, j, 0, 1):  # Try right first
                        break
                    elif place_block(color, i, j, 1, 0):  # Then down
                        break
                    else:
                        raise ValueError("Cannot place block for color {}".format(color))

    return grid

